def _classify_label(label: str) -> Tuple[str, bool]:
    """Split a data group label into its keyword and the projected flag."""

    body = label.lstrip("$").strip().lower()
    projected = "projected" in body
    # Only the leading token names the data group; qualifiers such as
    # '(projected)' or 'file=nprhessian' are additional producer information.
    keyword = re.split(r"[\s(]", body, maxsplit=1)[0].strip()
    return keyword, projected


def _is_curvature_keyword(keyword: str) -> bool:
    """Does a data group keyword name Cartesian force constants?"""

    return keyword in HESSIAN_KEYWORDS or "hessian" in keyword


def _curvature_blocks(text: str) -> List[_CurvatureBlock]:
    """Collect every force-constant representation contained in ``text``."""

    blocks = []
    groups = list(_iter_data_groups(text))
    for label, records in groups:
        keyword, projected = _classify_label(label)
        if not _is_curvature_keyword(keyword):
            continue
        values = [value for record in records for value in _record_values(record)]
        if not values:
            continue
        blocks.append(
            _CurvatureBlock(label=label, keyword=keyword, projected=projected, values=np.array(values, dtype=float))
        )

    if not blocks and not groups:
        # Records without any $-framing: the matrix is the whole payload.
        values = [value for line in text.split("\n") for value in _record_values(line)]
        if values:
            blocks.append(
                _CurvatureBlock(label="", keyword="", projected=False, values=np.array(values, dtype=float))
            )
    return blocks

